```php
function get_selected_variation( $product_id ) {
    $cart_contents = WC()->cart->get_cart_contents();
    foreach ( $cart_contents as $cart_item ) {
       if ( $cart_item['product_id'] == $product_id ) {
           $variation_id = $cart_item['variation_id'];
           if ( $variation_id ) {
               $variation_attributes = get_variation_attributes( $variation_id );
               // Do something with the variation attributes here.
               return $variation_attributes;
           }
       }
    }
    return false;
}

function get_variation_attributes( $variation_id ) {
    $variation = new WC_Product_Variation( $variation_id );
    return $variation->get_variation_attributes();
}
```

