// complete.
func walk(t *tree.Tree, ch chan int, done chan struct{}) {
    if t == nil {
        return
    }
    walk(t.Left, ch, done)
    ch <- t.Value
    walk(t.Right, ch, done)
    select {
    case <-done:
        return
    default:
    }
}

// Same determines whether the binary trees t1 and t2 contain the same values.
func Same(t1, t2 *tree.Tree) bool {
    ch1 := make(chan int)
    ch2 := make(chan int)
    done := make(chan struct{})
    defer close(done)
    go walk(t1, ch1, done)
    go walk(t2, ch2, done)
